// Extract results array for downstream processing
const results = $input.first().json.results || [];
return results.map(item => ({ json: item }));

// Deduplication using workflow static data
const staticData = $getWorkflowStaticData('global');
if (!staticData.processedIds) staticData.processedIds = [];

const radarId = $input.item.json.RadarID;

if (staticData.processedIds.includes(radarId)) {
  // Already processed — skip
  return [];
}

staticData.processedIds.push(radarId);

// Keep only last 10,000 IDs to prevent unbounded growth
if (staticData.processedIds.length > 10000) {
  staticData.processedIds = staticData.processedIds.slice(-10000);
}

return [$input.item];

// Merge property and owner data
const property = $('Deduplication1').item.json; // Original property data from loop
const owner = $json.persons?.[0] || $json[0] || {};

let score = 0;
const estValue = Number(property.EstValue) || 0;

// Property value scoring
if (estValue > 1000000) score += 40;
else if (estValue > 500000) score += 25;
else if (estValue > 250000) score += 15;
else score += 5;

// Contact info availability
if (owner.Email) score += 20;
if (owner.Phone) score += 20;

// Build tags
const tags = ['divorce-lead', 'propertyradar'];
if (score >= 50) tags.push('high-priority');

return [{
  json: {
    firstName: owner.FirstName || '',
    lastName: owner.LastName || '',
    email: owner.Email || '',
    phone: owner.Phone || '',
    address1: property.Address || '',
    city: property.City || '',
    state: property.State || '',
    postalCode: property.ZipFive || '',
    source: 'PropertyRadar - Divorce',
    tags: tags,
    leadScore: score,
    estValue: estValue,
    radarId: property.RadarID,
    county: property.County || '',
    divorceFilingDate: property.DivorceFilingDate || '',
    isHighValue: estValue > 500000
  }
}];

// Aggregate summary of all processed leads
const items = $('Lead Scoring & Transform1').all();
let totalLeads = items.length;
let highValueCount = 0;
const countsByCounty = {};

for (const item of items) {
  const d = item.json;
  if (d.isHighValue) highValueCount++;
  const county = d.county || 'Unknown';
  countsByCounty[county] = (countsByCounty[county] || 0) + 1;
}

const countyBreakdown = Object.entries(countsByCounty)
  .map(([county, count]) => `  ${county}: ${count}`)
  .join('\n');

const summary = `DAILY DIVORCE LEADS SUMMARY\n` +
  `Date: ${new Date().toISOString().split('T')[0]}\n\n` +
  `Total New Leads: ${totalLeads}\n` +
  `High-Value Leads (>$500k): ${highValueCount}\n\n` +
  `By County:\n${countyBreakdown || '  None'}\n\n` +
  `All leads have been pushed to Go High Level with tags and pipeline entries.`;

return [{ json: { summary, totalLeads, highValueCount } }];
